arguments.command:
cd /tmp/vally-eval-trial-j5D0K4 && cat > src/CheckoutPricing.Application/CalculatePayableTotal.cs <<'E'
namespace CheckoutPricing.Application;

public enum CustomerTier
{
    Standard,
    Gold
}

public sealed record CalculatePayableTotalRequest(CustomerTier Tier, decimal OrderSubtotal);

public sealed class CalculatePayableTotalHandler
{
    public decimal Handle(CalculatePayableTotalRequest request) => request.OrderSubtotal;
}
E
cat > tests/CheckoutPricing.UnitTests/LoyaltyDiscountAcceptanceTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests;

public sealed class LoyaltyDiscountAcceptanceTests
{
    [Fact]
    public void S1_GoldCustomerReceivesTheApprovedDiscount()
    {
        var handler = new CalculatePayableTotalHandler();

        var payableTotal = handler.Handle(new CalculatePayableTotalRequest(CustomerTier.Gold, 100.00m));

        Assert.Equal(95.00m, payableTotal);
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests --verbosity quiet 2>&1 | tail -20

